"""Independent full-protocol verifier used for development testing.

Written straight from PROTOCOL.md; deliberately does not share code with the
submission beyond the input validator.
"""
import json
import math

NUMS = (int, float)


def tol(a, b):
    return 1e-7 + 1e-7 * max(abs(a), abs(b))


def eq(a, b):
    return abs(a - b) <= tol(a, b)


def le(a, b):
    return a - b <= tol(a, b)


def ge(a, b):
    return b - a <= tol(a, b)


class Bad(Exception):
    pass


def is_num(v):
    return isinstance(v, NUMS) and not isinstance(v, bool) and math.isfinite(v)


def need_keys(d, keys, where):
    if not isinstance(d, dict):
        raise Bad(f'{where}: not an object')
    if set(d) != set(keys):
        raise Bad(f'{where}: keys {sorted(d)} != {sorted(keys)}')


def num_list(v, n, where, lo=None, hi=None):
    if not isinstance(v, list) or len(v) != n:
        raise Bad(f'{where}: expected list of {n} numbers, got {v if not isinstance(v,list) else len(v)}')
    for x in v:
        if not is_num(x):
            raise Bad(f'{where}: non numeric entry {x}')
        if lo is not None and x < lo:
            raise Bad(f'{where}: {x} < {lo}')
        if hi is not None and x > hi:
            raise Bad(f'{where}: {x} > {hi}')
    return [float(x) for x in v]


def id_list(v, where, strict=True, n=None):
    if not isinstance(v, list):
        raise Bad(f'{where}: not a list')
    for x in v:
        if not isinstance(x, int) or isinstance(x, bool):
            raise Bad(f'{where}: non int id {x}')
    if strict and any(v[i] >= v[i + 1] for i in range(len(v) - 1)):
        raise Bad(f'{where}: not strictly increasing {v}')
    if n is not None and (min(v, default=-1) < 0 or max(v, default=0) >= n):
        raise Bad(f'{where}: id out of range {v}')
    return list(v)


class CaseVerify:
    def __init__(self, case, resp, idx):
        self.idx = idx
        self.E = len(case['edges'])
        self.K = len(case['commodities'])
        self.W = len(case['workers'])
        self.owned = [list(w) for w in case['workers']]
        self.quorum = case['quorum']
        self.max_lag = case['max_lag']
        a, b = case['relax']
        self.alpha = a / b
        self.rho0 = case['rho']
        # verifier state
        self.g = 0
        self.r = 0
        self.cap = [float(e[2]) for e in case['edges']]
        self.dem = [float(c['demand']) for c in case['commodities']]
        self.slots = [list(c['paths']) for c in case['commodities']]
        self.mode = case['mode']
        self.rho = case['rho']
        self.A = [[0.0] * self.E for _ in range(self.W)]
        self.amounts = [[0.0] * len(s) for s in self.slots]
        self.z = [0.0] * self.E
        self.u = [0.0] * self.E
        self.seen = [False] * self.W
        self.fresh = [False] * self.W
        self.last = [None] * self.W
        self.seq = [None] * self.W
        self.tickets = {}
        self.receipts = set()
        self.checkpoints = {}
        self.counter = 0
        self.events = resp
        self.check_events(case['events'])

    def err(self, msg):
        raise Bad(f'case {self.idx}: {msg}')

    # ------------------------------------------------------------ helpers
    def live(self, e):
        return self.cap[e] > 0

    def totals(self):
        return [sum(self.A[w][e] for w in range(self.W)) for e in range(self.E)]

    def X(self):
        out = []
        S = self.totals()
        for e in range(self.E):
            out.append(S[e] / self.cap[e] if self.live(e) else 0.0)
        return out

    def check_events(self, events):
        if not isinstance(self.events, dict) or set(self.events) != {'events'}:
            self.err('case response must be exactly {"events":[...]}')
        results = self.events['events']
        if not isinstance(results, list) or len(results) != len(events):
            self.err(f'expected {len(events)} event results, got {len(results) if isinstance(results,list) else "?"}')
        for i, (ev, res) in enumerate(zip(events, results)):
            if not isinstance(res, dict) or res.get('op') != ev['op']:
                self.err(f'event {i}: result op mismatch {res.get("op") if isinstance(res,dict) else res}')
            op = ev['op']
            getattr(self, 'ev_' + op)(i, ev, res)

    # -------------------------------------------------------------- handlers
    def ev_configure(self, i, ev, res):
        for eid, val in ev['capacity']:
            self.cap[eid] = float(val)
        for kid, val in ev['demand']:
            self.dem[kid] = float(val)
        for kid, slot, path in ev['paths']:
            self.slots[kid][slot] = path
        self.mode = ev['mode']
        self.g += 1
        self.r = 0
        self.A = [[0.0] * self.E for _ in range(self.W)]
        self.amounts = [[0.0] * len(s) for s in self.slots]
        self.z = [0.0] * self.E
        self.u = [0.0] * self.E
        self.seen = [False] * self.W
        self.fresh = [False] * self.W
        self.last = [None] * self.W
        self.seq = [None] * self.W
        need_keys(res, ['op', 'generation'], f'event {i} configure')
        if res['generation'] != self.g or not isinstance(res['generation'], int):
            self.err(f'event {i}: configure generation {res["generation"]} != {self.g}')

    def ev_issue(self, i, ev, res):
        need_keys(res, ['op', 'id', 'worker', 'generation', 'bias', 'rho', 'result'], f'event {i} issue')
        tid = ev['id']
        w = ev['worker']
        if res['id'] != tid or res['worker'] != w or res['generation'] != self.g or res['rho'] != self.rho:
            self.err(f'event {i}: issue header mismatch')
        bias = num_list(res['bias'], self.E, f'event {i} bias')
        Xv = self.X()
        for e in range(self.E):
            if self.live(e):
                want = self.A[w][e] / self.cap[e] + (self.z[e] - Xv[e] - self.u[e]) / self.W
            else:
                want = 0.0
            if not eq(bias[e], want):
                self.err(f'event {i}: bias[{e}]={bias[e]} != {want}')
        seq = self.counter
        self.counter += 1
        self.tickets[tid] = {'seq': seq, 'worker': w, 'gen': self.g, 'rho': self.rho,
                             'mode': self.mode, 'bias': bias,
                             'cap': list(self.cap), 'dem': list(self.dem),
                             'slots': [list(s) for s in self.slots]}
        self.check_proposal(i, w, self.tickets[tid], res['result'])

    def available(self, slots, cap, k, t):
        path = slots[k][t]
        if path is None:
            return False
        return all(cap[e] > 0 for e in path)

    def check_proposal(self, i, w, snap, prop):
        owned = self.owned[w]
        cap, dem, slots, mode, rho, bias = snap['cap'], snap['dem'], snap['slots'], snap['mode'], snap['rho'], snap['bias']
        unroutable = sorted(k for k in owned if dem[k] > 0
                            and not any(self.available(slots, cap, k, t) for t in range(len(slots[k]))))
        if mode == 'route' and unroutable:
            need_keys(prop, ['status', 'unroutable'], f'event {i} infeasible proposal')
            if prop['status'] != 'infeasible':
                self.err(f'event {i}: expected infeasible proposal')
            got = id_list(prop['unroutable'], f'event {i} unroutable')
            if got != unroutable:
                self.err(f'event {i}: unroutable {got} != {unroutable}')
            snap['status'] = 'infeasible'
            return
        need_keys(prop, ['status', 'flow', 'edge_load', 'potential'], f'event {i} optimal proposal')
        if prop['status'] != 'optimal':
            self.err(f'event {i}: expected optimal proposal, got {prop["status"]}')
        if len(prop['flow']) != len(owned):
            self.err(f'event {i}: flow rows {len(prop["flow"])} != owned {len(owned)}')
        x = {}
        for pos, k in enumerate(owned):
            row = num_list(prop['flow'][pos], len(slots[k]), f'event {i} flow {k}', lo=0.0, hi=1e9)
            for t, v in enumerate(row):
                x[(k, t)] = v
        L = [0.0] * self.E
        for (k, t), v in x.items():
            if slots[k][t] is not None:
                for e in slots[k][t]:
                    L[e] += v
        load = num_list(prop['edge_load'], self.E, f'event {i} edge_load', lo=0.0, hi=1e9)
        for e in range(self.E):
            if not self.available_edge(cap, e) and load[e] != 0.0:
                self.err(f'event {i}: load on withdrawn edge {e} is {load[e]}')
            if not eq(L[e], load[e]):
                self.err(f'event {i}: edge_load[{e}]={load[e]} != recomputed {L[e]}')
        pot = num_list(prop['potential'], len(owned), f'event {i} potential', lo=-1e9, hi=1e9)
        if mode == 'admit' and any(p < 0 for p in pot):
            self.err(f'event {i}: negative admit potential')
        for pos, k in enumerate(owned):
            if dem[k] == 0 and pot[pos] != 0.0:
                self.err(f'event {i}: zero demand potential not exactly zero (commodity {k})')
            for t in range(len(slots[k])):
                if (not self.available(slots, cap, k, t)) or dem[k] <= 0:
                    if x[(k, t)] != 0.0:
                        self.err(f'event {i}: nonzero amount on unavailable slot {k}/{t}')
        sigma = 1.0 if mode == 'admit' else 0.0
        R = sum(x.values())
        f = 0.5 * sum(v * v for v in x.values()) + 0.5 * rho * sum(
            ((L[e] / cap[e] - bias[e]) ** 2 for e in range(self.E) if self.live(e))) - sigma * R
        G = {}
        for pos, k in enumerate(owned):
            if dem[k] <= 0:
                continue
            for t in range(len(slots[k])):
                if not self.available(slots, cap, k, t):
                    continue
                G[(k, t)] = x[(k, t)] + rho * sum(
                    ((L[e] / cap[e] - bias[e]) / cap[e] for e in slots[k][t])) - sigma
        lam = {k: pot[pos] for pos, k in enumerate(owned)}
        for pos, k in enumerate(owned):
            if dem[k] <= 0:
                continue
            for t in range(len(slots[k])):
                if not self.available(slots, cap, k, t):
                    continue
                if not ge(G[(k, t)] + lam[k], 0.0):
                    self.err(f'event {i}: G+lambda {G[(k,t)]+lam[k]} < 0 at {k}/{t}')
            ssum = sum(x[(k, t)] for t in range(len(slots[k])))
            if mode == 'route':
                if not eq(ssum, dem[k]):
                    self.err(f'event {i}: route demand {k} not served: {ssum} vs {dem[k]}')
            else:
                if not le(ssum, dem[k]):
                    self.err(f'event {i}: admit demand {k} exceeded: {ssum} vs {dem[k]}')
        D = f - sum(v * G[key] for key, v in G.items()) - sum(dem[k] * lam[k] for k in owned)
        if not eq(f, D):
            self.err(f'event {i}: certificate gap {abs(f-D)} > {tol(f,D)}')
        snap['status'] = 'optimal'
        snap['flow'] = [list(prop['flow'][pos]) for pos in range(len(owned))]
        snap['load'] = list(load)

    def available_edge(self, cap, e):
        return cap[e] > 0

    def ev_deliver(self, i, ev, res):
        need_keys(res, ['op', 'id', 'status'], f'event {i} deliver')
        tid = ev['id']
        if res['id'] != tid:
            self.err(f'event {i}: deliver id mismatch')
        snap = self.tickets[tid]
        w = snap['worker']
        if tid in self.receipts:
            status = 'duplicate'
        elif snap['gen'] != self.g:
            status = 'obsolete'
        elif self.seq[w] is not None and snap['seq'] < self.seq[w]:
            status = 'superseded'
        elif snap['status'] != 'optimal':
            status = 'infeasible'
        else:
            status = 'accepted'
            for pos, k in enumerate(self.owned[w]):
                self.amounts[k] = list(snap['flow'][pos])
            self.A[w] = list(snap['load'])
            self.seq[w] = snap['seq']
            self.seen[w] = True
            self.fresh[w] = True
            self.last[w] = self.r
        self.receipts.add(tid)
        if res['status'] != status:
            self.err(f'event {i}: deliver status {res["status"]} != {status}')

    def ev_step(self, i, ev, res):
        missing = [w for w in range(self.W) if not self.seen[w]]
        stale = [w for w in range(self.W) if self.seen[w] and self.r - self.last[w] > self.max_lag]
        fresh = [w for w in range(self.W) if self.fresh[w]]
        can = (not missing) and len(fresh) >= self.quorum and not stale
        if not can:
            need_keys(res, ['op', 'status', 'missing', 'stale', 'fresh'], f'event {i} blocked step')
            if res['status'] != 'waiting':
                self.err(f'event {i}: expected waiting step')
            if id_list(res['missing'], f'event {i} missing', n=self.W) != missing:
                self.err(f'event {i}: missing {res["missing"]} != {missing}')
            if id_list(res['stale'], f'event {i} stale', n=self.W) != stale:
                self.err(f'event {i}: stale {res["stale"]} != {stale}')
            if id_list(res['fresh'], f'event {i} fresh', n=self.W) != fresh:
                self.err(f'event {i}: fresh {res["fresh"]} != {fresh}')
            return
        need_keys(res, ['op', 'status', 'round', 'load', 'ceiling', 'z', 'dual', 'pressure'],
                  f'event {i} advanced step')
        if res['status'] != 'advanced':
            self.err(f'event {i}: expected advanced step')
        S = self.totals()
        num_list(res['load'], self.E, f'event {i} step load')
        for e in range(self.E):
            if not eq(res['load'][e], S[e]):
                self.err(f'event {i}: load[{e}] {res["load"][e]} != {S[e]}')
        Xv = self.X()
        znew = num_list(res['z'], self.E, f'event {i} z', lo=-1e9, hi=1e9)
        unew = num_list(res['dual'], self.E, f'event {i} dual', lo=-1e9, hi=1e9)
        pres = num_list(res['pressure'], self.E, f'event {i} pressure', lo=0.0, hi=1e9)
        h = res['ceiling']
        if not is_num(h) or h < 0 or h > 1e9:
            self.err(f'event {i}: bad ceiling {h}')
        live = [e for e in range(self.E) if self.live(e)]
        if not live:
            want_h = 0.0 if self.mode == 'route' else 1.0
            if abs(h - want_h) > 1e-9:
                self.err(f'event {i}: empty-live ceiling {h} != {want_h}')
        for e in range(self.E):
            if not self.live(e):
                if znew[e] != 0.0 or unew[e] != 0.0 or pres[e] != 0.0:
                    self.err(f'event {i}: withdrawn edge {e} has nonzero controller state')
                continue
            V = self.alpha * Xv[e] + (1.0 - self.alpha) * self.z[e] + self.u[e]
            if not eq(self.rho * (znew[e] - V) + pres[e], 0.0):
                self.err(f'event {i}: pressure identity fails on {e}: {self.rho*(znew[e]-V)+pres[e]}')
            if not eq(pres[e] * (h - znew[e]), 0.0):
                self.err(f'event {i}: complementarity on {e}: {pres[e]*(h-znew[e])}')
            if not le(znew[e], h):
                self.err(f'event {i}: z[{e}]={znew[e]} > h={h}')
            want_u = self.u[e] + self.alpha * Xv[e] + (1 - self.alpha) * self.z[e] - znew[e]
            if not eq(unew[e], want_u):
                self.err(f'event {i}: dual[{e}]={unew[e]} != {want_u}')
        if self.mode == 'route':
            tsum = sum(pres[e] for e in live)
            if not ge(1.0 - tsum, 0.0):
                self.err(f'event {i}: sum pressure {tsum} > 1')
            if not eq(h * (1.0 - tsum), 0.0):
                self.err(f'event {i}: ceiling complementarity {h*(1.0-tsum)}')
        else:
            if abs(h - 1.0) > tol(h, 1.0):
                self.err(f'event {i}: admit ceiling {h} != 1')
        self.z, self.u = znew, unew
        self.r += 1
        self.fresh = [False] * self.W
        if res['round'] != self.r or not isinstance(res['round'], int):
            self.err(f'event {i}: round {res["round"]} != {self.r}')

    def ev_retune(self, i, ev, res):
        need_keys(res, ['op', 'rho'], f'event {i} retune')
        old = self.rho
        new = ev['rho']
        self.rho = new
        if res['rho'] != new:
            self.err(f'event {i}: retune rho {res["rho"]} != {new}')
        for e in range(self.E):
            want = self.u[e] * old / new
            if not eq(self.u[e], self.u[e]):
                pass
            self.u[e] = want
        # (rho*u invariant is checked implicitly through later identities)

    def ev_save(self, i, ev, res):
        need_keys(res, ['op', 'name'], f'event {i} save')
        if res['name'] != ev['name']:
            self.err(f'event {i}: save name')
        self.checkpoints[ev['name']] = self.snapshot()

    def ev_restore(self, i, ev, res):
        need_keys(res, ['op', 'name', 'generation'], f'event {i} restore')
        if res['name'] != ev['name']:
            self.err(f'event {i}: restore name')
        self.load(self.checkpoints[ev['name']])
        self.g += 1
        if res['generation'] != self.g:
            self.err(f'event {i}: restore generation {res["generation"]} != {self.g}')

    def ev_audit(self, i, ev, res):
        need_keys(res, ['op', 'generation', 'round', 'rho', 'flow', 'worker_load', 'load',
                        'z', 'dual', 'seen', 'fresh', 'age'], f'event {i} audit')
        if res['generation'] != self.g:
            self.err(f'event {i}: audit generation')
        if res['round'] != self.r:
            self.err(f'event {i}: audit round {res["round"]} != {self.r}')
        if res['rho'] != self.rho:
            self.err(f'event {i}: audit rho {res["rho"]} != {self.rho}')
        if len(res['flow']) != self.K:
            self.err(f'event {i}: audit flow rows')
        for k in range(self.K):
            row = num_list(res['flow'][k], len(self.slots[k]), f'event {i} audit flow {k}', lo=0.0, hi=1e9)
            for t in range(len(row)):
                if not eq(row[t], self.amounts[k][t]):
                    self.err(f'event {i}: audit flow[{k}][{t}] {row[t]} != {self.amounts[k][t]}')
        if len(res['worker_load']) != self.W:
            self.err(f'event {i}: audit worker rows')
        for w in range(self.W):
            row = num_list(res['worker_load'][w], self.E, f'event {i} audit wload {w}', lo=0.0, hi=1e9)
            for e in range(self.E):
                if not eq(row[e], self.A[w][e]):
                    self.err(f'event {i}: audit worker_load[{w}][{e}] {row[e]} != {self.A[w][e]}')
        S = self.totals()
        load = num_list(res['load'], self.E, f'event {i} audit load')
        for e in range(self.E):
            if not eq(load[e], S[e]):
                self.err(f'event {i}: audit load {load[e]} != {S[e]}')
        z = num_list(res['z'], self.E, f'event {i} audit z', lo=-1e9, hi=1e9)
        u = num_list(res['dual'], self.E, f'event {i} audit dual', lo=-1e9, hi=1e9)
        for e in range(self.E):
            if not eq(z[e], self.z[e]) or not abs(z[e] - self.z[e]) <= tol(z[e], self.z[e]):
                self.err(f'event {i}: audit z {z[e]} != {self.z[e]}')
            if not eq(u[e], self.u[e]):
                self.err(f'event {i}: audit dual {u[e]} != {self.u[e]}')
        if id_list(res['seen'], f'event {i} audit seen', n=self.W) != [w for w in range(self.W) if self.seen[w]]:
            self.err(f'event {i}: audit seen mismatch')
        if id_list(res['fresh'], f'event {i} audit fresh', n=self.W) != [w for w in range(self.W) if self.fresh[w]]:
            self.err(f'event {i}: audit fresh mismatch')
        if not isinstance(res['age'], list) or len(res['age']) != self.W:
            self.err(f'event {i}: audit age shape')
        for w in range(self.W):
            want = None if not self.seen[w] else self.r - self.last[w]
            got = res['age'][w]
            if want is None:
                if got is not None:
                    self.err(f'event {i}: audit age[{w}] {got} != null')
            else:
                if not isinstance(got, int) or isinstance(got, bool) or got != want:
                    self.err(f'event {i}: audit age[{w}] {got} != {want}')

    # --------------------------------------------------------- checkpointing
    def snapshot(self):
        return {'cap': list(self.cap), 'dem': list(self.dem),
                'slots': [list(s) for s in self.slots], 'mode': self.mode, 'rho': self.rho,
                'r': self.r, 'z': list(self.z), 'u': list(self.u),
                'A': [list(row) for row in self.A],
                'amounts': [list(row) for row in self.amounts],
                'seen': list(self.seen), 'fresh': list(self.fresh),
                'last': list(self.last), 'seq': list(self.seq)}

    def load(self, snap):
        self.cap = list(snap['cap'])
        self.dem = list(snap['dem'])
        self.slots = [list(s) for s in snap['slots']]
        self.mode = snap['mode']
        self.rho = snap['rho']
        self.r = snap['r']
        self.z = list(snap['z'])
        self.u = list(snap['u'])
        self.A = [list(row) for row in snap['A']]
        self.amounts = [list(row) for row in snap['amounts']]
        self.seen = list(snap['seen'])
        self.fresh = list(snap['fresh'])
        self.last = list(snap['last'])
        self.seq = list(snap['seq'])


def verify(request, response, validate_request):
    validate_request(json.loads(json.dumps(request)))
    if not isinstance(response, dict) or set(response) != {'cases'}:
        raise Bad(f'response root {sorted(response) if isinstance(response,dict) else response}')
    cases = response['cases']
    if not isinstance(cases, list) or len(cases) != len(request['cases']):
        raise Bad('case count mismatch')
    for idx, (case, resp) in enumerate(zip(request['cases'], cases)):
        CaseVerify(case, resp, idx)
    return True
